// SPDX-License-Identifier: GPL-3.0-or-later
// Native-only storage ABI. Actual addresses are written and consumed on the
// GPU; JavaScript sees only the browser's opaque resource objects. A logical
// renderer buffer can exceed the browser's per-shared-allocation size limit.
template<class T> struct OmwPaged {
    const unsigned long long* pages;
    T* direct;
    unsigned long long first;
    __device__ OmwPaged(const unsigned long long* table):pages(table),direct(nullptr),first(0) {}
    __device__ OmwPaged(T* pointer):pages(nullptr),direct(pointer),first(0) {}
    template<class U> __device__ OmwPaged(const OmwPaged<U>& other):pages(other.pages),direct(other.direct),first(other.first) {}
    __device__ T& operator[](unsigned long long index) const {
        index+=first;
        if(direct)return direct[index];
        unsigned long long bytes=index*sizeof(T);
        return *reinterpret_cast<T*>(pages[bytes>>26]+(bytes&67108863ull));
    }
    __device__ OmwPaged operator+(unsigned long long offset) const {
        OmwPaged result=*this;result.first+=offset;return result;
    }
};

// SPDX-License-Identifier: GPL-3.0-or-later
// Source words retain the file's byte/float/half bits. GPU conversion and swizzle
// produce four float-bit atlas words per texel with requested storage precision.
// SPDX-License-Identifier: GPL-3.0-or-later
// Storage-format conversion, authored once for native CUDA and WebCuda.
// Rendering power bases and exponents are nonnegative. Spell out the float operation so
// WebCuda does not pull software f64 integer-power emulation into every shader.
// Zero is handled before log2, including the material convention pow(0,0)=1.
// Like GPU shader pow, this is approximate; it is not a general libm replacement.
__device__ float render_power(float base,float exponent) {


    if(exponent==0.0f||base==1.0f)return 1.0f;
    if(base==0.0f)return 0.0f;
    return exp2f(exponent*log2f(base));
}

__device__ unsigned int expand_half(unsigned int value) {


    unsigned int sign=(value&32768u)<<16,exponent=(value>>10)&31u,mantissa=value&1023u;
    if(exponent==31u)return sign|2139095040u|(mantissa<<13);
    if(exponent==0u) {
        if(mantissa==0u)return sign;
        unsigned int shift=0u;
        while((mantissa&1024u)==0u){mantissa=mantissa<<1;shift++;}
        return sign|((113u-shift)<<23)|((mantissa&1023u)<<13);
    }
    return sign|((exponent+112u)<<23)|(mantissa<<13);
}

__device__ unsigned int contract_half(float value) {


    unsigned int bits=__float_as_uint(value),sign=(bits>>16)&32768u;
    unsigned int exponent=(bits>>23)&255u,mantissa=bits&8388607u;
    if(exponent==255u)return sign|31744u|(mantissa!=0u?512u|(mantissa>>13):0u);
    int adjusted=(int)exponent-112;
    if(adjusted>=31)return sign|31744u;
    if(adjusted<=0) {
        if(adjusted< -10)return sign;
        mantissa|=8388608u;
        unsigned int shift=(unsigned int)(14-adjusted),rounded=mantissa>>shift;
        unsigned int remainder=mantissa&((1u<<shift)-1u),halfway=1u<<(shift-1u);
        if(remainder>halfway||(remainder==halfway&&(rounded&1u)!=0u))rounded++;
        return sign|rounded;
    }
    unsigned int rounded=mantissa+4095u+((mantissa>>13)&1u);
    if((rounded&8388608u)!=0u){rounded=0u;adjusted++;}
    if(adjusted>=31)return sign|31744u;
    return sign|((unsigned int)adjusted<<10)|(rounded>>13);
}
__device__ float round_half(float value) {


    return __uint_as_float(expand_half(contract_half(value)));
}

// sRGB atlas values are stored decoded, so filtering operates in linear space.
__device__ float srgb_to_linear(float value) {


    value=fminf(1.0f,fmaxf(0.0f,value));
    return value<=0.04045f?value/12.92f:render_power((value+0.055f)/1.055f,2.4f);
}
__device__ float linear_to_srgb(float value) {


    value=fminf(1.0f,fmaxf(0.0f,value));
    return value<=0.0031308f?value*12.92f:1.055f*render_power(value,1.0f/2.4f)-0.055f;
}

__device__ float store_color_value(float value,unsigned int channel,unsigned int channels,unsigned int storage) {


    if(channel>=channels)return channel==3u?1.0f:0.0f;
    if(storage==0u)return floorf(fminf(1.0f,fmaxf(0.0f,value))*255.0f+0.5f)/255.0f;
    if(storage==1u)return round_half(value);
    if(storage==4u)return floorf(fminf(1.0f,fmaxf(0.0f,value))*65535.0f+0.5f)/65535.0f;
    if(storage==5u||storage==6u) {
        float maximum=storage==5u?127.0f:32767.0f;
        return floorf(fminf(1.0f,fmaxf(-1.0f,value))*maximum+0.5f)/maximum;
    }
    if(storage==3u) {
        float encoded=channel<3u?linear_to_srgb(value):fminf(1.0f,fmaxf(0.0f,value));
        encoded=floorf(encoded*255.0f+0.5f)/255.0f;
        return channel<3u?srgb_to_linear(encoded):encoded;
    }
    return value;
}

__device__ float store_depth_value(float value,unsigned int bits) {


    value=fminf(1.0f,fmaxf(0.0f,value));
    if(bits==0u)return value;
    float maximum=bits==16u?65535.0f:16777215.0f;
    return fminf(1.0f,floorf(value*maximum+0.5f)/maximum);
}

__global__ void decode_float_image(const unsigned long long* omw_pages_blocks,const unsigned long long* omw_pages_pixels,
    unsigned int width,unsigned int height,unsigned int format,unsigned int block_offset,unsigned int pixel_offset) {
OmwPaged<const unsigned int> blocks(omw_pages_blocks);
OmwPaged<unsigned int> pixels(omw_pages_pixels);

    unsigned int i=(blockIdx.x+blockIdx.y*gridDim.x)*blockDim.x+threadIdx.x;
    if(i>=width*height)return;
    unsigned int destination_kind=(format>>8u)&15u,storage=(format>>12u)&7u,convert=format&65536u;
    unsigned int encoding=format&255u;
    unsigned int family=encoding/16u,kind=encoding%16u;
    unsigned int channels=(kind==6u||kind==13u)?4u:((kind==7u||kind==14u)?3u:((kind==8u||kind==11u)?2u:1u));
    unsigned int input[4];for(unsigned int k=0;k<4;k++)input[k]=k==3?1065353216u:0u;
    for(unsigned int k=0;k<channels;k++) {
        unsigned int index=i*channels+k;
        if(family>=8u) {
            unsigned int packed=family<14u?(blocks[block_offset+i/2u]>>((i%2u)*16u))&65535u:blocks[block_offset+i];
            unsigned int shift=0u,bits=8u;
            if(family==8u||family==9u) {
                bits=k==1u?6u:5u;
                shift=family==8u?(k==0u?11u:(k==1u?5u:0u)):(k==0u?0u:(k==1u?5u:11u));
            } else if(family==10u||family==11u) {
                bits=4u;shift=family==10u?(3u-k)*4u:k*4u;
            } else if(family==12u||family==13u) {
                bits=k==3u?1u:5u;
                shift=family==12u?(k==3u?0u:11u-k*5u):(k==3u?15u:k*5u);
            } else shift=family==14u?(3u-k)*8u:k*8u;
            unsigned int mask=(1u<<bits)-1u;
            input[k]=__float_as_uint((float)((packed>>shift)&mask)/(float)mask);
        }
        else if(family==0u)input[k]=blocks[block_offset+index];
        else if(family==1u)input[k]=expand_half((blocks[block_offset+index/2u]>>((index%2u)*16u))&65535u);
        else {
            unsigned int value;
            float decoded;
            if(family==2u||family==4u) {
                value=(blocks[block_offset+index/4u]>>((index%4u)*8u))&255u;
                decoded=family==2u?(float)value/255.0f:fmaxf(-1.0f,(float)((int)value-(value>=128u?256:0))/127.0f);
            } else if(family==3u||family==5u) {
                value=(blocks[block_offset+index/2u]>>((index%2u)*16u))&65535u;
                decoded=family==3u?(float)value/65535.0f:fmaxf(-1.0f,(float)((int)value-(value>=32768u?65536:0))/32767.0f);
            } else {
                value=blocks[block_offset+index];
                decoded=family==6u?(float)value/4294967295.0f:fmaxf(-1.0f,(float)((int)value)/2147483647.0f);
            }
            input[k]=__float_as_uint(decoded);
        }
    }
    // Depth images share the scalar float atlas ABI used by rendered depth
    // attachments. Floating depth retains its bits (including fallback +inf).
    if(convert!=0u&&destination_kind==9u) {
        pixels[pixel_offset+i]=storage==0u?input[0]:__float_as_uint(store_depth_value(__uint_as_float(input[0]),storage==1u?16u:24u));
        return;
    }
    float color[4];
    for(unsigned int k=0;k<4;k++) {
        unsigned int value=input[k];
        if(kind==10u||kind==11u)value=k==3u?(kind==11u?input[1]:1065353216u):input[0];
        if(kind==12u)value=k==3u?input[0]:0u;
        if((kind==13u||kind==14u)&&k<3u)value=input[2u-k];
        color[k]=__uint_as_float(value);
    }
    for(unsigned int k=0;k<4;k++) {
        float value=color[k];
        if(convert!=0u) {
            if(destination_kind==5u||destination_kind==6u)value=k==3u?(destination_kind==6u?color[3]:1.0f):color[0];
            if(destination_kind==7u)value=k==3u?color[3]:0.0f;
            if(destination_kind==8u)value=color[0];
            // Upload components already contain encoded sRGB values. Quantize
            // those values before decoding; mip generation starts in linear space.
            if(storage==3u) {
                value=store_color_value(value,k,destination_kind,0u);
                if(k<3u)value=srgb_to_linear(value);
            } else value=store_color_value(value,k,destination_kind>4u?4u:destination_kind,storage);
        }
        pixels[pixel_offset+i*4u+k]=__float_as_uint(value);
    }
}
